
(function(){
  const SCHEMA_VERSION='18.0';

  function migrateEmployee(e){
    const legacyGross=(Number(e.basic)||0)+(Number(e.housing)||0)+(Number(e.transport)||0)+(Number(e.other)||0);
    e.employmentType=e.employmentType||'Unassigned';
    e.payrollFrequency=e.payrollFrequency||'Unassigned';
    e.dailyRate=Number(e.dailyRate||0);
    e.monthlyRate=Number(e.monthlyRate||legacyGross);
    e.salaryComponents=e.salaryComponents||{
      basic:Number(e.basic||0),housing:Number(e.housing||0),transport:Number(e.transport||0),other:Number(e.other||0),
      bonus:0,overtime:0,commission:0,allowances:0
    };
    e.salaryComponents.basic=Number(e.salaryComponents.basic??e.basic??0);
    e.salaryComponents.housing=Number(e.salaryComponents.housing??e.housing??0);
    e.salaryComponents.transport=Number(e.salaryComponents.transport??e.transport??0);
    e.salaryComponents.other=Number(e.salaryComponents.other??e.other??0);
    e.monthlyRate=Number(e.monthlyRate||(
      e.salaryComponents.basic+e.salaryComponents.housing+e.salaryComponents.transport+e.salaryComponents.other
    ));
    // e.bank / e.account / e.bvn are the fields the employee-edit form actually reads and writes
    // (see saveEmployee) and are therefore the source of truth. bankDetails is a legacy mirror
    // object other parts of the app read from — it must always be freshly derived FROM the plain
    // fields, never treated as its own source, or an edit to e.bank gets silently reverted the
    // next time this migration runs (this was exactly the dept/position/status bug described
    // below, just not yet fixed for bank details).
    e.bankDetails=e.bankDetails||{};
    e.bankDetails.bankName=e.bank||'';
    e.bankDetails.accountNumber=e.account||'';
    e.bankDetails.accountName=e.accountName||e.bankDetails.accountName||e.name||'';
    e.bankDetails.sortCode=e.sortCode||e.bankDetails.sortCode||'';
    e.bankDetails.bankCode=e.bankCode||e.bankDetails.bankCode||'';
    e.bankDetails.bvn=e.bvn||e.bankDetails.bvn||'';
    // departmentId/positionId/employmentStatus started life as migration-era mirrors of
    // dept/position/status. The bug: they were only ever set the FIRST time (via ||), so once an
    // employee had gone through this once, editing dept/position/status through the normal form
    // had no visible effect — this function would run again on save, find the mirror field
    // already truthy, leave it alone, and then overwrite dept/position/status FROM the stale
    // mirror at the end, silently reverting the very edit that was just made. The fix: the field
    // the edit form actually writes to (dept/position/status) is the source of truth and always
    // wins; the mirror just tracks whatever that currently is.
    e.departmentId=e.dept||e.departmentId||'';
    e.positionId=e.position||e.positionId||'';
    // Unlike dept/position (where the plain field is what the form writes to and the "Id" field
    // is the legacy mirror), employmentStatus is itself the field the newer form writes to, and
    // status is the mirror — so the priority here is intentionally the other way around.
    e.employmentStatus=e.employmentStatus||e.status||'Active';
    e.employmentStartDate=e.employmentStartDate||e.dateEmployed||e.joinDate||'';
    e.employmentEndDate=e.employmentEndDate||e.exitDate||'';
    e.managerId=e.managerId||'';e.location=e.location||'';
    e.payrollEligible=e.payrollEligible!==false;
    e.dataQuality=e.employmentType==='Unassigned'||e.payrollFrequency==='Unassigned'?'Review Required':'Complete';
    e.basic=e.salaryComponents.basic;e.housing=e.salaryComponents.housing;e.transport=e.salaryComponents.transport;e.other=e.salaryComponents.other;
    e.dept=e.departmentId;e.position=e.positionId;e.status=e.employmentStatus;
    e.gross=e.salaryComponents.basic+e.salaryComponents.housing+e.salaryComponents.transport+e.salaryComponents.other;
    return e;
  }

  db.employees=(db.employees||[]).map(migrateEmployee);
  db.schemaVersion=SCHEMA_VERSION;
  db.payrollCycles=db.payrollCycles||[];db.bankPaymentFiles=db.bankPaymentFiles||[];db.payrollRuns=db.payrollRuns||[];
  db.deductions=db.deductions||[];db.paymentBatches=db.paymentBatches||[];db.security=db.security||{roles:[],permissions:[],sessions:[]};
  db.payrollSettings=db.payrollSettings||{weeklyWorkingDays:6,monthlyWorkingDays:26,casualPayBasis:'Approved Attendance',rounding:'2dp',overtimeMultiplier:1.5,defaultCurrency:'NGN',bankFileFormat:'CSV'};

  db.databaseSchema={
    employees:{pk:'employee_id',fields:['employee_id','employee_code','full_name','employment_type','payroll_frequency','employment_status','department_id','position_id','manager_id','start_date','end_date','location','phone','email','address','gender','dob','marital_status','state_of_origin','next_of_kin','emergency_contact','payroll_eligible','created_at','updated_at']},
    compensation:{pk:'compensation_id',fk:['employee_id'],fields:['employee_id','effective_from','effective_to','basic','housing','transport','other','bonus','overtime','commission','allowances','gross_rate','currency','reason','status']},
    bank_accounts:{pk:'bank_account_id',fk:['employee_id'],fields:['employee_id','bank_name','bank_code','sort_code','account_name','account_number','bvn','is_primary','verified_at','status']},
    payroll_cycles:{pk:'cycle_id',fields:['cycle_id','frequency','period_start','period_end','pay_date','status','prepared_by','reviewed_by','approved_by','locked_at']},
    payroll_runs:{pk:'run_id',fk:['cycle_id'],fields:['cycle_id','employee_id','employment_type','payable_days','rate','earnings','deductions','gross','net','status','calculation_snapshot']},
    payroll_items:{pk:'payroll_item_id',fk:['run_id','employee_id'],fields:['run_id','employee_id','component_code','component_type','amount','taxable','pensionable']},
    attendance:{pk:'attendance_id',fk:['employee_id'],fields:['employee_id','work_date','status','time_in','time_out','payable_day','approved_by','approved_at','source']},
    leave_requests:{pk:'leave_request_id',fk:['employee_id'],fields:['employee_id','leave_type','start_date','end_date','days','reason','status','requested_at','approved_by','approved_at']},
    leave_balances:{pk:'leave_balance_id',fk:['employee_id'],fields:['employee_id','leave_type','year','opening_balance','used_days','remaining_days']},
    hr_records:{pk:'hr_record_id',fk:['employee_id'],fields:['employee_id','record_type','effective_date','details','status','created_by']},
    documents:{pk:'document_id',fk:['employee_id'],fields:['employee_id','document_type','reference','issue_date','expiry_date','storage_key','status','notes']},
    actions:{pk:'action_id',fk:['employee_id'],fields:['employee_id','action_type','effective_date','payload','status','requested_by','approved_by']},
    payments:{pk:'payment_id',fk:['payroll_run_id','employee_id'],fields:['payroll_run_id','employee_id','batch_id','bank_account_id','amount','currency','payment_reference','status','submitted_at','confirmed_at']},
    payment_batches:{pk:'batch_id',fields:['batch_id','cycle_id','total_items','total_amount','bank_file_name','file_format','status','created_by','authorized_by']},
    security_users:{pk:'user_id',fields:['user_id','employee_id','username','status','last_access_at']},
    security_roles:{pk:'role_id',fields:['role_id','role_name']},
    security_permissions:{pk:'permission_id',fields:['permission_id','permission_code']},
    user_roles:{pk:'user_role_id',fk:['user_id','role_id'],fields:['user_id','role_id']},
    audit_log:{pk:'audit_id',fields:['timestamp','user_id','action','entity','entity_id','details','ip_or_device','result']}
  };
  save();

  const nav=document.querySelector('nav');
  if(nav){
    nav.innerHTML=`
      <button class="active" onclick="showPage('dashboard',this)">▦ Dashboard</button>
      <button onclick="showPage('employees',this)">👥 Employees</button>
      <button onclick="showPage('attendance2',this)">◷ Attendance & Time</button>
      <button onclick="showPage('leave',this)">▱ Leave</button>
      <button onclick="showPage('payroll',this)">₦ Payroll</button>
      <button onclick="showPage('paycycles',this)">↻ Payroll Cycles</button>
      <button onclick="showPage('paymentflow',this)">⇄ Bank Payments</button>
      <button onclick="showPage('payslips',this)">▤ Payslips</button>
      <button onclick="showPage('hrrecords',this)">▣ HR Records</button>
      <button onclick="showPage('lifecycle',this)">⚙ HR Actions</button>
      <button onclick="showPage('compensation',this)">◆ Compensation</button>
      <button onclick="showPage('ess',this)">♙ Employee Portal</button>
      <button onclick="showPage('security',this)">◉ Security, Reports & Settings</button>`;
    nav.id='mainNav';
  }

  document.body.insertAdjacentHTML('afterbegin',`
    <div class="marlum-login" id="marlumLogin">
      <div class="marlum-login-photo">
        <div class="marlum-login-photo-img" style="background-image:url(data:image/avif;base64,)"></div>
        <div class="marlum-login-photo-img" style="background-image:url(data:image/avif;base64,)"></div>
        <div class="marlum-login-photo-img" style="background-image:url(data:image/webp;base64,)"></div>
        <div class="marlum-login-top">
          <div class="marlum-login-lockup"><div class="login-mark">M</div><span class="login-lockup-rule"></span><div class="login-lockup-text"><b>Marlum</b><span>HR &amp; Payroll</span></div></div>
          <div class="marlum-login-tagline">Build better teams. Run work smarter.</div>
        </div>
        <div class="marlum-login-bottom">
          <div class="marlum-login-dots" aria-hidden="true"><i></i><i></i><i></i></div>
          <div class="marlum-login-features">
            <div class="marlum-login-feature"><svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="3"/><path d="M6.5 20v-1a5.5 5.5 0 0 1 11 0v1"/><circle cx="4.8" cy="10.5" r="2"/><path d="M1.5 19v-.3a3.3 3.3 0 0 1 3.3-3.3"/><circle cx="19.2" cy="10.5" r="2"/><path d="M22.5 19v-.3a3.3 3.3 0 0 0-3.3-3.3"/></svg><span>Manage<br>Your People</span></div>
            <div class="marlum-login-feature"><svg viewBox="0 0 24 24"><ellipse cx="9.5" cy="5.5" rx="6" ry="2.4"/><path d="M3.5 5.5v4c0 1.3 2.7 2.4 6 2.4M3.5 9.5v4c0 1.3 2.7 2.4 6 2.4"/><circle cx="17" cy="16.5" r="4.6"/><path d="M17 14v5M18.5 15.1c-.4-.5-1-.7-1.5-.7-.9 0-1.5.5-1.5 1.2 0 1.6 3.1.8 3.1 2.4 0 .7-.7 1.2-1.6 1.2-.7 0-1.2-.3-1.6-.7"/></svg><span>Automate<br>Payroll</span></div>
            <div class="marlum-login-feature"><svg viewBox="0 0 24 24"><path d="M12 2.5 19.5 5.5v5.7c0 4.6-3.1 8.2-7.5 10.3-4.4-2.1-7.5-5.7-7.5-10.3V5.5z"/><path d="m8.6 12 2.3 2.3 4.5-4.6"/></svg><span>Stay<br>Compliant</span></div>
          </div>
        </div>
      </div>
      <div class="marlum-login-formside">
      <div class="login-card">
        <div class="marlum-login-lockup"><div class="login-mark">M</div><span class="login-lockup-rule"></span><div class="login-lockup-text"><b>Marlum</b><span>HR &amp; Payroll</span></div></div><h1>Welcome Back</h1><p>Sign in to your account to continue</p>
        <label><span class="sr-only">Email address</span><input id="loginUser" type="email" placeholder="Email address" autocomplete="username"></label>
        <label><span class="sr-only">Password</span><div class="password-wrap"><input id="loginPass" type="password" placeholder="Password" autocomplete="current-password"><button type="button" class="password-toggle" onclick="togglePasswordVisibility('loginPass',this)" aria-label="Show password"><svg viewBox="0 0 24 24"><path d="M3 3l18 18"/><path d="M10.6 5.2A9.6 9.6 0 0 1 12 5c5 0 8.5 4.2 9.5 7-.4 1-1.2 2.4-2.5 3.7M6.6 6.7C4.4 8.1 3 10.2 2.5 12c1 2.8 4.5 7 9.5 7 1.6 0 3-.4 4.2-1"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></button></div></label>
        <p id="marlumAuthStatus" class="marlum-auth-status" style="display:none"></p>
        <button class="login-btn" id="authPrimaryBtn" type="button" onclick="marlumAuthSubmit()">Sign In</button>
        <div class="auth-links">
          <label class="remember-me"><input type="checkbox" id="authRemember"> Remember me</label>
          <a href="javascript:void(0)" id="authForgotLink" onclick="marlumV19ResetPassword()">Forgot password?</a>
        </div>
        <p class="login-note" id="authNote">Secure &nbsp;&bull;&nbsp; Reliable &nbsp;&bull;&nbsp; Built for Your Team</p>
      </div>
      </div>
    </div>
    <button class="mobile-menu" onclick="document.getElementById('mainNav')?.classList.toggle('open')">☰</button>
    <button class="side-toggle" onclick="toggleSidebar()">☰ Sidebar</button>`);

  // window.enterMarlum removed entirely — it set Super Admin access directly from whatever text was
  // typed in the username field (defaulting to 'admin' if left blank), with no password check
  // whatsoever, and its own log message admitted as much: "Authentication bypass enabled for
  // development." It was never wired to any visible button in this build's actual login form — the
  // real login uses marlumV19SignIn() against real Supabase authentication — but the function itself
  // was still fully callable by anyone through their browser's console. Same class of issue as the
  // demo-role login already removed, and treated with the same zero-tolerance fix: gone completely,
  // not hidden.
  window.toggleSidebar=function(){document.getElementById('mainNav')?.classList.toggle('open')};

  const sec=document.getElementById('security');
  if(sec){
    const extra=document.createElement('div');extra.className='card';extra.style.marginTop='15px';
    extra.innerHTML=`<h3>Control Centre</h3><p class="label">Security and audit remain here. Reporting, company settings and the technical schema are available without adding more sidebar sections.</p>
      <div class="toolbar"><button class="btn secondary" onclick="showPage('reports',this)">Open Reports</button><button class="btn secondary" onclick="showPage('settings',this)">Open Settings</button><button class="btn secondary" onclick="openDatabaseSchema()">Database Schema</button></div>`;
    sec.appendChild(extra);
  }

  window.openEmployee=function(id=null){
    const e=migrateEmployee(db.employees.find(x=>x.id===id)||{id:'',name:'',dept:'',position:'',employmentType:'Unassigned',payrollFrequency:'Unassigned',dailyRate:0,monthlyRate:0,basic:0,housing:0,transport:0,other:0,bank:'',account:'',bvn:'',status:'Active'});
    openModal(`<h3>${id?'Edit':'Add'} Employee</h3><div class="form">
      <div class="employee-form-section"><h4>Identity & Employment</h4></div>
      <label>Employee ID<input id="e_id" value="${esc(e.id)}" ${id?'readonly':''}></label><label>Full Name<input id="e_name" value="${esc(e.name)}"></label>
      <label>Department<input id="e_dept" value="${esc(e.dept)}"></label><label>Position / Job Title<input id="e_pos" value="${esc(e.position)}"></label>
      <label>Employment Type<select id="e_employmentType">${['Fixed Salary','Casual','Contract','Temporary','Unassigned'].map(x=>`<option ${e.employmentType===x?'selected':''}>${x}</option>`).join('')}</select></label>
      <label>Payroll Frequency<select id="e_payrollFrequency">${['Monthly','Weekly','Unassigned'].map(x=>`<option ${e.payrollFrequency===x?'selected':''}>${x}</option>`).join('')}</select></label>
      <label>Employment Status<select id="e_status">${['Active','Inactive','Resigned','Terminated'].map(x=>`<option ${e.employmentStatus===x?'selected':''}>${x}</option>`).join('')}</select></label>
      <label>Date Employed<input id="e_dateEmployed" type="date" value="${esc(e.employmentStartDate)}"></label><label>End Date<input id="e_endDate" type="date" value="${esc(e.employmentEndDate)}"></label>
      <label>Supervisor / Manager<input id="e_manager" value="${esc(e.managerId)}"></label><label>Location / Site<input id="e_location" value="${esc(e.location)}"></label><label>Grade Level<input id="e_grade" value="${esc(e.grade||'')}"></label>
      <div class="employee-form-section"><h4>Payroll Rate & Salary Components</h4></div>
      <label>Daily Rate (Casual)<input id="e_dailyRate" type="number" min="0" step="0.01" value="${e.dailyRate||0}"><div class="form-help">Approved payable days × daily rate.</div></label>
      <label>Monthly Rate (Fixed)<input id="e_monthlyRate" type="number" min="0" step="0.01" value="${e.monthlyRate||0}"></label>
      <label>Basic Salary<input id="e_basic" type="number" min="0" step="0.01" value="${e.salaryComponents.basic||0}"></label><label>Housing Allowance<input id="e_housing" type="number" min="0" step="0.01" value="${e.salaryComponents.housing||0}"></label>
      <label>Transport Allowance<input id="e_transport" type="number" min="0" step="0.01" value="${e.salaryComponents.transport||0}"></label><label>Other Allowance<input id="e_other" type="number" min="0" step="0.01" value="${e.salaryComponents.other||0}"></label>
      <label>Recurring Allowances<input id="e_allowances" type="number" min="0" step="0.01" value="${e.salaryComponents.allowances||0}"></label><label>Default Overtime<input id="e_overtime" type="number" min="0" step="0.01" value="${e.salaryComponents.overtime||0}"></label>
      <div class="employee-form-section"><h4>Bank & Payment Details</h4></div>
      <label>Bank Name<input id="e_bank" value="${esc(e.bank||'')}" oninput="autoFillBankCode()" onblur="autoFillBankCode(true)"></label><label>Account Name<input id="e_accountName" value="${esc(e.accountName||e.name)}"></label>
      <label>Account Number<input id="e_account" value="${esc(e.account||'')}" maxlength="10"></label><label>Bank Code (filled in automatically)<input id="e_bankCode" value="${esc(e.bankCode||'')}" readonly style="background:#f4f1ee"></label>
      <div id="e_bankCodeWarning" style="grid-column:1/-1"></div>
      <label>Sort Code<input id="e_sortCode" value="${esc(e.sortCode||'')}"></label><label>BVN<input id="e_bvn" value="${esc(e.bvn||'')}" maxlength="11"></label>
      <div class="employee-form-section"><h4>Personal & Contact</h4></div>
      <label>Gender<select id="e_gender"><option value="">Select</option><option ${e.gender==='Male'?'selected':''}>Male</option><option ${e.gender==='Female'?'selected':''}>Female</option></select></label>
      <label>Date of Birth<input id="e_dob" type="date" value="${esc(e.dob||'')}"></label><label>Marital Status<select id="e_marital"><option value="">Select</option><option ${e.marital==='Single'?'selected':''}>Single</option><option ${e.marital==='Married'?'selected':''}>Married</option><option ${e.marital==='Divorced'?'selected':''}>Divorced</option><option ${e.marital==='Widowed'?'selected':''}>Widowed</option></select></label>
      <label>Phone<input id="e_phone" value="${esc(e.phone||'')}"></label><label>Email<input id="e_email" type="email" value="${esc(e.email||'')}"></label><label>Residential Address<input id="e_address" value="${esc(e.address||'')}"></label>
      <label>State of Origin<input id="e_state" value="${esc(e.state||'')}"></label><label>Next of Kin<input id="e_nextOfKin" value="${esc(e.nextOfKin||'')}"></label><label>Emergency Contact<input id="e_emergency" value="${esc(e.emergency||'')}"></label>
    </div><div class="toolbar"><button class="btn primary" onclick="saveEmployeeV18('${esc(id||'')}')">Save Employee</button><button class="btn secondary" onclick="closeModal()">Cancel</button></div>`);
    autoFillBankCode(true); // check the bank name immediately on opening, so a pre-existing unrecognized name surfaces right away rather than only after it's retyped
  };

  window.saveEmployeeV18=function(oldId){
    const id=document.getElementById('e_id').value.trim(),name=document.getElementById('e_name').value.trim();
    if(!id||!name){alert('Employee ID and name are required.');return}
    if(db.employees.some(x=>x.id===id&&x.id!==oldId)){alert(oldId?`Employee ID "${id}" already belongs to a different employee — choose a different ID.`:'Employee ID already exists.');return}
    const existing=db.employees.find(x=>x.id===oldId)||{};
    const components={basic:+document.getElementById('e_basic').value||0,housing:+document.getElementById('e_housing').value||0,transport:+document.getElementById('e_transport').value||0,other:+document.getElementById('e_other').value||0,allowances:+document.getElementById('e_allowances').value||0,overtime:+document.getElementById('e_overtime').value||0,bonus:existing.salaryComponents?.bonus||0,commission:existing.salaryComponents?.commission||0};
    const obj={...existing,id,name,dept:document.getElementById('e_dept').value.trim(),position:document.getElementById('e_pos').value.trim(),
      employmentType:document.getElementById('e_employmentType').value,payrollFrequency:document.getElementById('e_payrollFrequency').value,employmentStatus:document.getElementById('e_status').value,
      dateEmployed:document.getElementById('e_dateEmployed').value,employmentStartDate:document.getElementById('e_dateEmployed').value,employmentEndDate:document.getElementById('e_endDate').value,
      managerId:document.getElementById('e_manager').value,location:document.getElementById('e_location').value,grade:document.getElementById('e_grade').value,dailyRate:+document.getElementById('e_dailyRate').value||0,monthlyRate:+document.getElementById('e_monthlyRate').value||0,
      salaryComponents:components,
      // bank/account/etc (the plain fields) are what migrateEmployee treats as the source of
      // truth for bankDetails, so they must be set directly here from the form — setting only
      // bankDetails and leaving these as whatever {...existing} spread in would mean the very
      // next migration pass overwrites this edit right back to the old value.
      bank:document.getElementById('e_bank').value.trim(),account:document.getElementById('e_account').value.trim(),accountName:document.getElementById('e_accountName').value.trim(),bankCode:document.getElementById('e_bankCode').value.trim(),sortCode:document.getElementById('e_sortCode').value.trim(),bvn:document.getElementById('e_bvn').value.trim(),
      bankDetails:{bankName:document.getElementById('e_bank').value.trim(),accountName:document.getElementById('e_accountName').value.trim(),accountNumber:document.getElementById('e_account').value.trim(),bankCode:document.getElementById('e_bankCode').value.trim(),sortCode:document.getElementById('e_sortCode').value.trim(),bvn:document.getElementById('e_bvn').value.trim(),isPrimary:true},
      gender:document.getElementById('e_gender').value,dob:document.getElementById('e_dob').value,marital:document.getElementById('e_marital').value,phone:document.getElementById('e_phone').value,email:document.getElementById('e_email').value,address:document.getElementById('e_address').value,state:document.getElementById('e_state').value,nextOfKin:document.getElementById('e_nextOfKin').value,emergency:document.getElementById('e_emergency').value};
    migrateEmployee(obj);
    const oldGross=Number(existing.gross||0),newGross=Number(obj.gross||0);
    if(oldId){const i=db.employees.findIndex(x=>x.id===oldId);db.employees[i]=obj;if(oldGross!==newGross){db.salaryHistory=db.salaryHistory||[];db.salaryHistory.push({emp:id,effective:todayISO(),...components,gross:obj.gross,source:'Employee Master'})}log('Employee master updated',`${id} — ${name}`)}
    else{db.employees.push(obj);log('Employee master created',`${id} — ${name}`)}
    save();closeModal();render();
  };

  window.viewEmployee=function(id){
    const e=migrateEmployee(db.employees.find(x=>x.id===id));if(!e)return;const gross=salaryGross(e.salaryComponents);
    const hist=[...(db.salaryHistory||[]).filter(x=>x.emp===id).map(x=>({...x,status:'Historical'})),...(db.salaryChanges||[]).filter(x=>x.emp===id).map(x=>({...x,status:x.status}))].sort((a,b)=>String(b.effective||b.effectiveDate).localeCompare(String(a.effective||a.effectiveDate)));
    const checks=[['Employment type',e.employmentType!=='Unassigned'],['Payroll frequency',e.payrollFrequency!=='Unassigned'],['Rate',e.employmentType==='Casual'?e.dailyRate>0:e.monthlyRate>0],['Bank account',String(e.account||'').length>=10],['Department',!!e.dept],['Position',!!e.position]];
    openModal(`<h3>${esc(e.name)} — Employee Master Profile</h3><div class="grid">
      <div class="card"><div class="label">Employee ID</div><b>${esc(e.id)}</b></div><div class="card"><div class="label">Employment Type</div><b>${esc(e.employmentType)}</b></div><div class="card"><div class="label">Payroll Frequency</div><b>${esc(e.payrollFrequency)}</b></div>
      <div class="card"><div class="label">Department</div><b>${esc(e.dept||'—')}</b></div><div class="card"><div class="label">Position</div><b>${esc(e.position||'—')}</b></div><div class="card"><div class="label">Status</div><b>${esc(e.employmentStatus)}</b></div>
      <div class="card"><div class="label">Daily Rate</div><b>${money(e.dailyRate)}</b></div><div class="card"><div class="label">Monthly Rate</div><b>${money(e.monthlyRate)}</b></div><div class="card"><div class="label">Monthly Gross Components</div><b>${money(gross)}</b></div></div>
      <h4>Salary Components</h4><table><tr><th>Basic</th><th>Housing</th><th>Transport</th><th>Other</th><th>Allowances</th><th>Overtime</th><th>Gross</th></tr>
      <tr><td>${money(e.salaryComponents.basic)}</td><td>${money(e.salaryComponents.housing)}</td><td>${money(e.salaryComponents.transport)}</td><td>${money(e.salaryComponents.other)}</td><td>${money(e.salaryComponents.allowances)}</td><td>${money(e.salaryComponents.overtime)}</td><td><b>${money(gross)}</b></td></tr></table>
      <h4>Bank Details</h4><table><tr><th>Bank</th><th>Account Name</th><th>Account</th><th>Bank Code</th><th>BVN</th></tr><tr><td>${esc(e.bankDetails.bankName||'—')}</td><td>${esc(e.bankDetails.accountName||'—')}</td><td>${e.account?'****'+esc(e.account.slice(-4)):'—'}</td><td>${esc(e.bankDetails.bankCode||'—')}</td><td>${e.bankDetails.bvn?'********'+esc(e.bankDetails.bvn.slice(-3)):'—'}</td></tr></table>
      <p class="label">Bank Code above is for reference only — the actual bank payment file works out the correct code automatically from the Bank Name, every time, so this field being blank or out of date never affects a payment run.</p>
      <h4>Master Data Completeness</h4><p>${checks.map(x=>`<span class="badge ${x[1]?'active-b':'pending'}">${x[1]?'✓':'Review'} ${esc(x[0])}</span>`).join(' ')}</p>
      <h4>Salary History</h4><table><tr><th>Effective</th><th>Gross</th><th>Reason / Source</th><th>Status</th></tr>${hist.map(x=>`<tr><td>${esc(x.effective||x.effectiveDate||'—')}</td><td>${money(x.gross??salaryGross(x))}</td><td>${esc(x.reason||x.source||'Salary record')}</td><td>${esc(x.status||'—')}</td></tr>`).join('')||'<tr><td colspan="4">No salary revisions recorded.</td></tr>'}</table>
      <div class="toolbar"><button class="btn primary" onclick="openEmployee('${esc(e.id)}')">Edit Master</button><button class="btn secondary" onclick="closeModal()">Close</button></div>`);
  };

  window.renderEmployees=function(){
    const q=(document.getElementById('employeeSearch')?.value||'').toLowerCase().trim(),el=document.getElementById('employeeRows');if(!el)return;
    const rows=db.employees.map(migrateEmployee).filter(e=>!q||[e.id,e.name,e.dept,e.position,e.employmentType,e.payrollFrequency,e.bank,e.phone,e.email].join(' ').toLowerCase().includes(q));
    el.innerHTML=rows.map(e=>{const g=salaryGross(e.salaryComponents),review=e.dataQuality==='Review Required';const canDelete=normalizeRoles(activeSystemUser()).includes('Super Admin');return `<tr><td>${esc(e.id)}</td><td><b>${esc(e.name)}</b>${review?'<div class="form-help">Master data review</div>':''}</td><td>${esc(e.dept||'—')}</td><td>${esc(e.position||'—')}</td><td>${esc(e.employmentType)}</td><td>${esc(e.payrollFrequency)}</td><td>${e.employmentType==='Casual'?money(e.dailyRate):money(g)}</td><td>${esc(e.bank||'—')} / ${e.account?'****'+esc(e.account.slice(-4)):'—'}</td><td><span class="badge ${e.status==='Active'?'active-b':'failed'}">${esc(e.status)}</span></td><td><button class="btn secondary" onclick="viewEmployee('${esc(e.id)}')">View</button> <button class="btn secondary" onclick="openEmployee('${esc(e.id)}')">Edit</button> ${canDelete?`<button class="btn danger" onclick="deleteEmployee('${esc(e.id)}')">Delete</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="10">No matching employees.</td></tr>';
  };
  const empTable=document.querySelector('#employees table thead tr');if(empTable)empTable.innerHTML='<th>ID</th><th>Employee</th><th>Department</th><th>Position</th><th>Employment Type</th><th>Frequency</th><th>Rate / Gross</th><th>Bank</th><th>Status</th><th>Action</th>';

  // (payableDays, payrollComponents, and calculateEmployeePay removed entirely — a third, separate
  // copy of the same dead logic from the old single-draft payroll system, missed in the previous
  // removal pass since it sat in a different part of this same module. Confirmed zero remaining
  // callers before removing. The correct, current, live version of this calculation is
  // calculateCycleEmployee, already extensively tested elsewhere in this file.)
  // window.createPayroll, bankRows, window.exportBankPaymentFile, and window.prepareBatch removed
  // entirely — all four were part of the old, single-draft "Payroll" system built on db.payroll, a
  // variable nothing in the current Payroll Cycle system has set in a long time (confirmed elsewhere
  // in this file: every one of these already carried a "Calculate payroll first" guard that could
  // never actually pass). csvDownload is kept — it's shared with the live Export CSV feature on
  // Employee Management.
  function csvDownload(rows,name){const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click()}

  const pf=document.getElementById('paymentflow');if(pf){const bar=pf.querySelector('.toolbar');if(bar)bar.innerHTML='<button class="btn secondary" onclick="openPaymentBatches()">Payment Batches</button><button class="btn secondary" onclick="openApprovalQueue()">Approval Queue</button>';const note=pf.querySelector('p.label');if(note)note.textContent='Payment batches are created from within an approved, locked Payroll Cycle. This page is a register of every batch created that way, whatever its current stage.';}
  const payments=document.getElementById('payments');if(payments){const b=payments.querySelector('.toolbar');if(b)b.innerHTML='<button class="btn primary" onclick="prepareBatch()">Prepare Payment Batch</button><button class="btn secondary" onclick="exportBankPaymentFile()">Export Bank Payment CSV</button><button class="btn success" onclick="authorizeBatch()">Authorize & Simulate Bank Submission</button>'}

  window.exportEmployees=function(){const rows=[['Employee ID','Full Name','Employment Type','Payroll Frequency','Employment Status','Department','Position','Daily Rate','Monthly Rate','Basic','Housing','Transport','Other','Allowances','Overtime','Gross','Bank','Account Number','Bank Code','Account Name','Phone','Email','Date Employed']];db.employees.map(migrateEmployee).forEach(e=>rows.push([e.id,e.name,e.employmentType,e.payrollFrequency,e.employmentStatus,e.dept,e.position,e.dailyRate,e.monthlyRate,e.salaryComponents.basic,e.salaryComponents.housing,e.salaryComponents.transport,e.salaryComponents.other,e.salaryComponents.allowances,e.salaryComponents.overtime,e.gross,e.bankDetails.bankName,e.bankDetails.accountNumber,e.bankDetails.bankCode,e.bankDetails.accountName,e.phone,e.email,e.employmentStartDate]));csvDownload(rows,'marlum-employees-master.csv');log('Employee master CSV exported',`${db.employees.length} employees`)};

  window.openDatabaseSchema=function(){const rows=Object.entries(db.databaseSchema).map(([name,s])=>`<tr><td><b>${esc(name)}</b></td><td>${esc(s.pk)}</td><td>${esc((s.fk||[]).join(', ')||'—')}</td><td><code>${esc(s.fields.join(', '))}</code></td></tr>`).join('');openModal(`<h3>Marlum Database Schema v${SCHEMA_VERSION}</h3><p class="label">Browser build: localStorage. The schema below is the normalized contract for the future secure database/API.</p><div class="schema-card"><table><tr><th>Entity</th><th>Primary Key</th><th>Foreign Keys</th><th>Fields</th></tr>${rows}</table></div><button class="btn secondary" onclick="closeModal()">Close</button>`)};

  function injectDashboard(){const d=document.getElementById('dashboard');if(!d)return;d.innerHTML=`<div class="marlum-dash-head"><div><h2>Payroll Control Dashboard</h2><div class="label">Marlum Nigeria Ltd. · Workforce, payroll and payment control centre</div></div><span class="live-pill">● Live data</span></div>
    <div class="metric-grid">
    <div class="metric-card clickable-card" onclick="navToPage('employees')" title="Go to Employee Management"><div class="label">Active Employees</div><div class="metric" id="mEmployees">0</div><div class="metric-sub" id="mEmployeeSub"></div></div>
    <div class="metric-card clickable-card" onclick="navToPage('paycycles')" title="Go to Payroll Cycle"><div class="label">Current Gross Payroll</div><div class="metric" id="mGross">₦0</div><div class="metric-sub" id="mGrossSub"></div></div>
    <div class="metric-card clickable-card" onclick="navToPage('paycycles')" title="Go to Payroll Cycle"><div class="label">Current Net Payroll</div><div class="metric" id="mNet">₦0</div><div class="metric-sub" id="mNetSub"></div></div>
    <div class="metric-card clickable-card" onclick="navToPage('attendance2')" title="Go to Attendance & Time Management"><div class="label">Attendance Today</div><div class="metric" id="mAttendance">0%</div><div class="metric-sub" id="mAttendanceSub"></div><div class="mini-bar"><span id="mAttendanceBar" style="width:0%"></span></div></div></div>
    <div class="dash-two"><div class="card"><h3>Payroll Control Status</h3><div id="controlStatus"></div></div><div class="card"><h3>Pending Actions</h3><div id="dashActions" class="action-list"></div></div></div>
    <div class="card" style="margin-top:14px"><h3>Data Quality</h3><div id="dashDataQuality"></div><div class="toolbar"><button class="btn secondary" onclick="navToPage('employees')">Review Employee Master</button></div></div>`}
  window.navToPage=function(pageId){
    const btn=document.querySelector(`#mainNav .nav-item[data-page="${pageId}"]`);
    if(typeof window.navGoV191==='function')window.navGoV191(pageId,btn);
    else if(typeof window.showPage==='function')window.showPage(pageId,btn);
  };
  injectDashboard();

  const oldRender=window.render;
  function updateDashboard(){
    const active=db.employees.filter(e=>e.status==='Active'),p=db.payroll,gross=p?.totals?.gross??(p?.items||[]).reduce((a,x)=>a+x.gross,0),net=p?.totals?.net??(p?.items||[]).reduce((a,x)=>a+x.netPay,0);
    const d=todayISO(),atts=attendanceRecords().filter(x=>x.date===d&&x.approvalStatus==='Approved'),present=atts.filter(x=>x.status==='Present'||x.status==='Half Day').length,attendanceRate=active.length?Math.round(present/active.length*100):0;
    document.getElementById('mEmployees').textContent=active.length;document.getElementById('mEmployeeSub').textContent=`${active.filter(e=>e.employmentType==='Casual').length} casual · ${active.filter(e=>e.employmentType==='Fixed Salary').length} fixed`;
    document.getElementById('mGross').textContent=money(gross);document.getElementById('mGrossSub').textContent=p?`${p.items.length} payroll lines`:'Payroll not calculated';
    document.getElementById('mNet').textContent=money(net);document.getElementById('mNetSub').textContent=p?`Deductions ${money(gross-net)}`:'—';
    document.getElementById('mAttendance').textContent=attendanceRate+'%';document.getElementById('mAttendanceSub').textContent=`${present} of ${active.length} present`;document.getElementById('mAttendanceBar').style.width=attendanceRate+'%';
    const pending=[['Employee master review',db.employees.filter(e=>e.dataQuality==='Review Required').length,'employees'],['Pending HR actions',(db.hrActions||[]).filter(x=>x.status==='Pending').length,'lifecycle'],['Pending salary changes',(db.salaryChanges||[]).filter(x=>x.status==='Pending').length,'compensation'],['Payment batches in progress',(db.paymentBatches||[]).filter(x=>!['Paid','Reconciled'].includes(x.status)).length,'paycycles']];
    document.getElementById('dashActions').innerHTML=pending.map(x=>`<div class="action-item clickable-card" onclick="navToPage('${x[2]}')"><span><span class="status-dot"></span>${esc(x[0])}</span><b>${x[1]}</b></div>`).join('');
    const complete=active.filter(e=>e.dataQuality==='Complete').length,pct=active.length?Math.round(complete/active.length*100):0;document.getElementById('dashDataQuality').innerHTML=`<b>${pct}% complete</b> · ${complete} of ${active.length} active employees have employment type, payroll frequency, rate, department, position and bank account master data.`;
  }
  window.render=function(){if(typeof oldRender==='function')oldRender();db.employees.forEach(migrateEmployee);updateDashboard()};

  const empPage=document.getElementById('employees');if(empPage&&!document.getElementById('employeeMasterNotice')){const n=document.createElement('div');n.id='employeeMasterNotice';n.className='notice';n.innerHTML='<b>Single source of truth:</b> Employment type, payroll frequency, rate, salary components, bank details, department, position and employment status now drive payroll, attendance and bank payments.';empPage.insertBefore(n,empPage.querySelector('table'))}

  window.__marlumDB=db; window.__marlumSave=save; window.__marlumLog=log;


  setTimeout(()=>{try{render()}catch(e){console.error(e)}},0);
})();
